/**
 * What New chat's and a conversation's composers share: the images it takes (admin-api's limits, the
 * smaller total on Cloudflare), whether the assistant can search the web, the attachments a message
 * sends, and how an assistant is named (`assistantName`). The "/" menu lists only the commands the App
 * registered (`agent.command`, `GET /admin/api/commands`, read by the shell): the dashboard's own
 * actions (stop, reset, images, web search, the assistant, the views) are its buttons, never commands.
 */

import type { ComposerImage, ImageLimits, PickerOption } from "@/components/bui/PromptBar";
import { IMAGE_TYPES, MAX_DURABLE_IMAGE_BYTES, MAX_IMAGE_BYTES, MAX_IMAGES, WEB_SEARCH_TOOL } from "@/lib/admin-api";
import type { ApiAgent, ApiApp, ApiAttachment } from "@/lib/api";
import { assistantName } from "@/lib/names";

export { assistantName };

export const imageLimits = (app: ApiApp): ImageLimits => ({
  types: IMAGE_TYPES,
  count: MAX_IMAGES,
  bytes: MAX_IMAGE_BYTES,
  ...(app.target === "durable" && { totalBytes: MAX_DURABLE_IMAGE_BYTES }),
});

/** Whether `agent` searches the web (it has `WEB_SEARCH_TOOL`), and why not. */
export function webSearchOf(agents: ApiAgent[] | undefined, agent: string | undefined): { available: boolean; unavailable: string } {
  const found = agents?.find((each) => each.name === agent);
  return {
    available: found?.tools.includes(WEB_SEARCH_TOOL) === true,
    unavailable: agents === undefined ? "The assistants are not read yet" : `${agent === undefined ? "This assistant" : assistantName(agent)} has no web search tool`,
  };
}

export const attachmentsOf = (images: ComposerImage[]): ApiAttachment[] => images.map(({ mimeType, data }) => ({ kind: "image", mimeType, data }));

/** The assistants as the composer's picker lists them: by their shown name, `tag`s for some. */
export const assistantOptions = (names: string[], tag: (name: string) => string | undefined = () => undefined): PickerOption[] =>
  names.map((name) => {
    const tagged = tag(name);
    return { key: name, name: assistantName(name), ...(tagged !== undefined && { tag: tagged }) };
  });

/**
 * One conversation, live, in the shared view (`components/pikit/conversation.tsx`) over the admin API
 * (`source.ts`); and what an operator does to it (SPEC §5): a message (with images, a web search), a
 * stop, a reset (`/new`). Its top bar holds an info button on who it is with (`PartyChip`: its Details,
 * the channel, the name, the ids, a link to where the channel shows them), the Context panel's button, when there is any (the images
 * sent in it, what its web searches and fetches found), and its menu (Rename, Archive or Restore,
 * Delete: the sidebar row's). Its composer shows its assistant: a conversation never changes agent, so
 * picking another starts a new chat with it. Its "/" runs the App's commands here (`POST
 * …/commands/:name`): what one answers is a quiet note in the thread, for the operator only (no channel
 * gets it); one that left the conversation behind (`/new`) is followed to its key's new conversation,
 * the note with it.
 *
 * The dashboard is a channel of its own: a message from here is a follow-up (it waits for a run
 * going) whose answer stays here. In another channel's conversation nothing said here reaches that
 * channel's chat (the agent reads that the message is the operator's, and that the user sees neither
 * it nor the answer); a run that also answers a user's message is delivered to the user, as always.
 *
 * With an outbound queue (`lib/delivery-feed.ts`, read once for the whole dashboard), an answer of this
 * conversation the queue gave up, or that is stuck in it, gets a quiet note in the thread where the
 * queue says it was (an answer is stored when its run ends; one given up after 24 hours is noted when
 * it was): "Not delivered: <why>", with a link to Delivery.
 */

import { Clock, WarningTriangle } from "iconoir-react";
import { useCallback, useEffect, useMemo } from "react";
import { ActionsMenu } from "@/components/bui/ActionsMenu";
import { ConversationView, type ThreadNote } from "@/components/pikit/conversation";
import { ErrorNote } from "@/components/pikit/error-note";
import { PartyChip, partyOf } from "@/components/pikit/party";
import { api, type ApiCommandResponse, type ApiConversation, type ApiPage, post, useApi } from "@/lib/api";
import { agentsOf, type CommandNote, useChats } from "@/lib/chats";
import type { StuckAnswer, UndeliveredAnswer } from "@/lib/delivery";
import { useDelivery } from "@/lib/delivery-feed";
import { formatAgo } from "@/lib/format";
import { Link, navigate, pagePath } from "@/lib/router";
import { SidePanel, TabActions, useShell } from "@/lib/shell";
import { assistantOptions, imageLimits, webSearchOf } from "./composer";
import { adminSource } from "./source";

/** What a command answered: a quiet note in the thread, the operator's only. */
function CommandNoteRow({ note }: { note: CommandNote }) {
  return (
    <div className="flex items-start gap-2.5 rounded-card bg-inset px-3 py-2.5 shadow-hairline" style={{ animation: "fade-up 320ms cubic-bezier(0.23,1,0.32,1) both" }}>
      <span className="mt-px flex h-5 shrink-0 items-center rounded-chip bg-surface px-1.5 font-mono chat-text-11.5 text-ink-2 shadow-hairline">/{note.command}</span>
      <p className="min-w-0 flex-1 chat-text-13 leading-5 text-ink-2 [overflow-wrap:anywhere]">{note.text}</p>
      <span className="mt-0.5 shrink-0 chat-text-11 text-ink-3">Only you see this</span>
    </div>
  );
}

/** An answer of this conversation the queue gave up, or holds stuck: a quiet note, a link to Delivery. */
function DeliveryNoteRow({ answer }: { answer: { kind: "undelivered"; of: UndeliveredAnswer } | { kind: "stuck"; of: StuckAnswer } }) {
  const undelivered = answer.kind === "undelivered";
  const text = undelivered
    ? `Not delivered: ${answer.of.reason}`
    : answer.of.retrying
      ? `Not delivered yet: retrying${answer.of.lastError === undefined ? "" : ` (${answer.of.lastError})`}`
      : "Not delivered yet: waiting to be sent";
  const Icon = undelivered ? WarningTriangle : Clock;
  return (
    <div role="note" className="flex items-start gap-2.5 rounded-card bg-inset px-3 py-2.5 shadow-hairline" style={{ animation: "fade-up 320ms cubic-bezier(0.23,1,0.32,1) both" }}>
      <Icon width={15} height={15} strokeWidth={1.9} aria-hidden className={`mt-0.5 shrink-0 ${undelivered ? "text-red" : "text-orange"}`} />
      <p className="min-w-0 flex-1 chat-text-13 leading-5 text-ink-2 [overflow-wrap:anywhere]">{text}</p>
      <span className="mt-0.5 shrink-0 chat-text-11 text-ink-3">
        {undelivered ? `Given up ${formatAgo(answer.of.at)}` : `Since ${formatAgo(answer.of.since)}`} ·{" "}
        <Link to="/delivery" className="underline-offset-2 hover:text-ink hover:underline">
          Delivery
        </Link>
      </span>
    </div>
  );
}

export function ConversationPage({ params }: { params: Record<string, string> }) {
  const id = params.id ?? "";
  const chats = useChats();
  const { app, agents: described, commands, newChat, conversationActions } = useShell();
  const agents = agentsOf(app, described);
  const delivery = useDelivery((app.capabilities["outbound.queue"]?.providers.length ?? 0) > 0).problems;
  const source = useMemo(() => adminSource(id), [id]);
  const summary = useApi<ApiConversation>(`/conversations/${encodeURIComponent(id)}`);
  const { reload } = summary;
  const conversation = summary.data?.conversationId === id ? summary.data : undefined;

  const { openTab, setFirstMessage } = chats;
  useEffect(() => {
    if (conversation !== undefined) openTab(conversation);
  }, [conversation, openTab]);

  // Until the API titles it, a chat is named by the first words written in it, once read here.
  const onFirstText = useCallback(
    (text: string) => {
      if (conversation !== undefined && conversation.title === undefined) setFirstMessage(conversation.conversationId, text);
    },
    [conversation, setFirstMessage],
  );

  if (summary.error !== undefined) {
    return (
      <div className="mx-auto w-full max-w-[720px] p-8">
        <ErrorNote error={summary.error} title="This conversation cannot be read" />
      </div>
    );
  }

  /**
   * Runs `/name args` here. Its note stays in this page; a command that left this conversation behind
   * (`/new`) is followed to its key's current one, which gets the note. What fails, the view shows.
   */
  const runCommand = async (name: string, args: string) => {
    if (conversation === undefined) return;
    const answer = await post<ApiCommandResponse>(`/conversations/${encodeURIComponent(conversation.conversationId)}/commands/${encodeURIComponent(name)}`, { args });
    let target = conversation.conversationId;
    const now = await api<ApiConversation>(`/conversations/${encodeURIComponent(conversation.conversationId)}`).catch(() => undefined);
    if (now?.current === false && now.key !== undefined) {
      const page = await api<ApiPage<ApiConversation>>("/conversations?limit=50").catch(() => undefined);
      target = page?.items.find((each) => each.key === now.key && each.current === true)?.conversationId ?? target;
    }
    chats.addNote(target, name, answer.text ?? `Ran /${name}.`);
    chats.reload();
    if (target === conversation.conversationId) reload();
    else {
      chats.replaced(conversation.conversationId, target);
      navigate(pagePath("/conversations", target), { replace: true });
    }
  };

  const notes: ThreadNote[] = [
    ...chats.notesOf(id).map((note) => ({ key: `note-${note.id}`, at: note.at, node: <CommandNoteRow note={note} /> })),
    ...(delivery?.undelivered ?? [])
      .filter((answer) => answer.conversationId === id)
      .map((answer) => ({ key: `undelivered-${answer.key}`, at: answer.at, node: <DeliveryNoteRow answer={{ kind: "undelivered", of: answer }} /> })),
    ...(delivery?.stuck ?? [])
      .filter((answer) => answer.conversationId === id)
      .map((answer) => ({ key: `stuck-${answer.key}`, at: answer.since, node: <DeliveryNoteRow answer={{ kind: "stuck", of: answer }} /> })),
  ].sort((a, b) => a.at - b.at);
  const archived = chats.archived?.some((each) => each.conversationId === id) === true;

  return (
    <ConversationView
      source={source}
      sent={chats}
      context={conversation !== undefined}
      onChange={reload}
      onFirstText={onFirstText}
      notes={notes}
      actions={(contextButton) =>
        conversation !== undefined && (
          <TabActions>
            <PartyChip party={partyOf(conversation)} />
            {contextButton}
            <ActionsMenu
              actions={conversationActions(conversation, archived)}
              label="Conversation actions"
              // Archived or not: the archived ones are read when the menu opens.
              onOpenChange={(open) => open && chats.archived === undefined && chats.loadArchived()}
              className="size-7 rounded-[7px] text-ink-3 transition-colors duration-100 hover:bg-hover hover:text-ink aria-expanded:bg-hover-2 aria-expanded:text-ink"
            />
          </TabActions>
        )
      }
      side={(panel) => <SidePanel>{panel}</SidePanel>}
      closed={
        conversation !== undefined && conversation.current !== true ? (
          <p className="rounded-card bg-inset px-3 py-2.5 chat-text-13 text-ink-2 shadow-hairline">
            {conversation.current === false ? "A reset left this conversation behind: it can be read, not talked to." : "No message has reached this conversation yet."}
          </p>
        ) : undefined
      }
      composer={{
        disabled: conversation === undefined,
        picker:
          conversation?.agent === undefined
            ? undefined
            : {
                label: "assistant",
                options: assistantOptions(agents.includes(conversation.agent) ? agents : [conversation.agent, ...agents], (name) => (name !== conversation.agent ? "new chat" : undefined)),
                value: conversation.agent,
                onChange: (agent) => newChat(agent),
                ...(agents.some((name) => name !== conversation.agent) && { note: "A chat keeps its assistant: another one starts a new chat with it." }),
              },
        images: imageLimits(app),
        webSearch: webSearchOf(described, conversation?.agent),
        commands: commands ?? [],
        onCommand: runCommand,
      }}
    />
  );
}

import { ChatBubble } from "iconoir-react";
import { defineView } from "@/lib/views";
import { ConversationPage } from "./conversation";
import { CONVERSATIONS_PATH, ConversationsPage } from "./list";
import { NewChatPage } from "./new-chat";

/**
 * The chat: New chat (`/conversations`: a new conversation of the dashboard's own), every
 * conversation (`/conversations/:id`), and the list of them all (`/conversations/all`, before `:id`:
 * the first page that matches is shown). The shell lists the latest in its sidebar and tabs, and links
 * the list ("Conversations", "View all"), not as a view.
 */
export default defineView({
  id: "conversations",
  title: "Chats",
  icon: ChatBubble,
  requires: ["agent.observe"],
  order: 10,
  pages: [
    { path: "/conversations", component: NewChatPage, fill: true },
    { path: CONVERSATIONS_PATH, component: ConversationsPage, fill: true },
    { path: "/conversations/:id", component: ConversationPage, fill: true },
  ],
});

/**
 * Conversations (`/conversations/all`): every conversation, the most recently active first, a page at
 * a time ("Load more", the API's cursor), where the sidebar lists only the latest (`SIDEBAR_CHATS`,
 * its "View all" leads here). A search finds them by title or key (`?q=`, the API's: any case), as the
 * operator stops typing; "Archived" lists the archived ones instead (`?archived=1`), searched alike:
 * the only place they are. Each row shows its channel's icon, and opens its conversation, and its menu is the sidebar row's (Rename,
 * Archive or Restore, Delete: `useShell().conversationActions`); a change made anywhere here reads the
 * list again (`useChats().changed`).
 */

import { Archive, ChatBubble, Plus, Search } from "iconoir-react";
import { useEffect, useState } from "react";
import { Button } from "@/components/bui/Button";
import { ConversationList } from "@/components/bui/ConversationList";
import EmptyState from "@/components/bui/EmptyState";
import { LoaderGrid } from "@/components/bui/LoadingState";
import { Page } from "@/components/bui/Page";
import SearchField from "@/components/bui/SearchField";
import { Switch } from "@/components/bui/Switch";
import { ErrorNote } from "@/components/pikit/error-note";
import { ChannelIcon, partyOf } from "@/components/pikit/party";
import { SEARCH_MAX } from "@/lib/admin-api";
import { api, type ApiConversation, type ApiPage } from "@/lib/api";
import { useChats } from "@/lib/chats";
import { BASE, navigate, pagePath } from "@/lib/router";
import { useShell } from "@/lib/shell";

/** The list's path. */
export const CONVERSATIONS_PATH = "/conversations/all";
const PAGE = 30;
/** How long after the last key a search goes. */
const DEBOUNCE_MS = 250;

/** `value`, once it stopped changing for `ms`. */
function useDebounced<T>(value: T, ms: number): T {
  const [settled, setSettled] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setSettled(value), ms);
    return () => clearTimeout(timer);
  }, [value, ms]);
  return settled;
}

const pathOf = ({ q, archived, cursor }: { q: string; archived: boolean; cursor?: string }): string => {
  const params = new URLSearchParams({ limit: String(PAGE) });
  if (archived) params.set("archived", "1");
  if (q !== "") params.set("q", q);
  if (cursor !== undefined) params.set("cursor", cursor);
  return `/conversations?${params}`;
};

/** The conversations `q` finds, archived or not: `undefined` until read; read again when `round` moves. More pages on demand. */
function useFound(q: string, archived: boolean, round: number) {
  const key = `${archived}:${q}`;
  const [found, setFound] = useState<{ key: string; items: ApiConversation[]; next?: string | undefined }>();
  const [error, setError] = useState<Error>();

  useEffect(() => {
    let live = true;
    api<ApiPage<ApiConversation>>(pathOf({ q, archived })).then(
      (page) => live && (setFound({ key, items: page.items.filter((each) => each.key !== undefined), next: page.next }), setError(undefined)),
      (thrown: unknown) => live && setError(thrown instanceof Error ? thrown : new Error(String(thrown))),
    );
    return () => {
      live = false;
    };
  }, [key, q, archived, round]);

  const current = found?.key === key ? found : undefined;
  const loadMore = async () => {
    if (current?.next === undefined) return;
    const page = await api<ApiPage<ApiConversation>>(pathOf({ q, archived, cursor: current.next }));
    const ids = new Set(current.items.map((each) => each.conversationId));
    setFound({ key, items: [...current.items, ...page.items.filter((each) => each.key !== undefined && !ids.has(each.conversationId))], next: page.next });
  };
  return { items: current?.items, error, hasMore: current?.next !== undefined, loadMore };
}

export function ConversationsPage() {
  const chats = useChats();
  const { newChat, conversationActions } = useShell();
  const [query, setQuery] = useState("");
  const [archived, setArchived] = useState(false);
  const [loading, setLoading] = useState(false);
  const [problem, setProblem] = useState<Error>();
  const q = useDebounced(query.trim(), DEBOUNCE_MS);
  const found = useFound(q, archived, chats.changed);
  const items = found.items;

  return (
    <Page
      eyebrow="Conversations"
      title="Every chat with the App"
      aside={
        <Button variant="primary" size="xs" onClick={() => newChat()}>
          <Plus width={14} height={14} strokeWidth={2} aria-hidden /> New chat
        </Button>
      }
    >
      <section className="flex flex-col gap-3">
        <div className="flex flex-wrap items-center gap-3">
          <SearchField value={query} onChange={(value) => setQuery(value.slice(0, SEARCH_MAX))} placeholder="Search by title" label="Search the conversations" className="min-w-0 flex-1" />
          <label className="flex shrink-0 cursor-pointer items-center gap-2 text-[13px] text-ink-2">
            <Switch checked={archived} onChange={setArchived} size="sm" label="Archived" />
            <span aria-hidden>Archived</span>
          </label>
        </div>
        {found.error !== undefined && <ErrorNote error={found.error} title="The conversations cannot be read" />}
        {problem !== undefined && <ErrorNote error={problem} />}
        {items === undefined && found.error === undefined && (
          <div className="flex items-center gap-2.5 text-[13px] text-ink-3">
            <LoaderGrid /> Loading
          </div>
        )}
        {items !== undefined && items.length === 0 && (
          <EmptyState
            icon={q !== "" ? <Search /> : archived ? <Archive /> : <ChatBubble />}
            title={q !== "" ? `No ${archived ? "archived " : ""}conversation with “${q}”` : archived ? "No archived conversations" : "No conversations yet"}
            hint={q !== "" ? "Search finds words of a title, or of a key, in any case." : archived ? "A conversation you archive is listed here." : "Start one with New chat, or wait for a channel's."}
          />
        )}
        {items !== undefined && items.length > 0 && (
          <ConversationList
            items={items.map((conversation) => {
              const { channel } = partyOf(conversation);
              return {
                id: conversation.conversationId,
                title: chats.titleOf(conversation),
                icon: <ChannelIcon kind={channel.kind} label={channel.label} />,
                href: `${BASE}${pagePath("/conversations", conversation.conversationId)}`,
                lastActivity: conversation.lastActivity,
                busy: conversation.busy,
                actions: conversationActions(conversation, archived),
              };
            })}
            onOpen={(id) => navigate(pagePath("/conversations", id))}
          />
        )}
        {found.hasMore && (
          <Button
            size="xs"
            className="self-center"
            disabled={loading}
            aria-busy={loading}
            onClick={() => {
              setLoading(true);
              setProblem(undefined);
              found
                .loadMore()
                .catch((error: unknown) => setProblem(error instanceof Error ? error : new Error(String(error))))
                .finally(() => setLoading(false));
            }}
          >
            {loading ? "Loading" : "Load more"}
          </Button>
        )}
      </section>
    </Page>
  );
}

/**
 * New chat: a new conversation of the dashboard's own. The operator picks one of the App's agents (in
 * the composer, where Beautiful UI picks a model; `?agent=<name>` chooses one, as a conversation's
 * composer does when another is picked there) and writes the first message, with images and a web
 * search when wanted: `POST /admin/api/conversations` makes `dashboard:<uuid>`, whose answers appear
 * only here, and no other channel can continue it. Below, the last conversations, to continue. The
 * "/" menu lists the App's commands, which run in a conversation: here, they say so.
 */

import { ChatBubble } from "iconoir-react";
import { type CSSProperties, useEffect, useState } from "react";
import PromptBar, { type ComposerMessage } from "@/components/bui/PromptBar";
import { ErrorNote } from "@/components/pikit/error-note";
import { type ApiStartResponse, post } from "@/lib/api";
import { agentsOf, defaultAgentOf, NEW_CHAT, useChats } from "@/lib/chats";
import { Link, navigate, pagePath } from "@/lib/router";
import { useShell } from "@/lib/shell";
import { assistantName, assistantOptions, attachmentsOf, imageLimits, webSearchOf } from "./composer";

/* -- the entrance (ms after mount): hello, question, composer, suggestions -- */
const REVEAL_TIMING = [170, 330, 400, 550];
const REVEAL = { offsetY: 23, blur: 17, duration: 800, easing: "cubic-bezier(0.16, 1, 0.3, 1)" };
/** The conversations suggested: the most recently active. */
const SUGGESTED = 3;

function revealStyle(visible: boolean): CSSProperties {
  return {
    opacity: visible ? 1 : 0,
    transform: visible ? "translate3d(0, 0, 0)" : `translate3d(0, ${REVEAL.offsetY}px, 0)`,
    filter: visible ? "blur(0px)" : `blur(${REVEAL.blur}px)`,
    transition: ["opacity", "transform", "filter"].map((property) => `${property} ${REVEAL.duration}ms ${REVEAL.easing}`).join(", "),
  };
}

export function NewChatPage() {
  const { app, agents: described, commands, operator } = useShell();
  const chats = useChats();
  const agents = agentsOf(app, described);
  const [agent, setAgent] = useState<string | undefined>(() => new URLSearchParams(window.location.search).get("agent") ?? undefined);
  const [error, setError] = useState<Error>();
  const [stage, setStage] = useState(0);
  const chosen = agent !== undefined && agents.includes(agent) ? agent : defaultAgentOf(app);
  const fallback = defaultAgentOf(app);
  const webSearch = webSearchOf(described, chosen);

  useEffect(() => {
    const timers = REVEAL_TIMING.map((at, i) => setTimeout(() => setStage(i + 1), at));
    return () => timers.forEach(clearTimeout);
  }, []);

  const start = async ({ text, images, webSearch: search }: ComposerMessage) => {
    if (chosen === undefined) return;
    setError(undefined);
    try {
      const started = await post<ApiStartResponse>("/conversations", { agent: chosen, text, ...(images.length > 0 && { attachments: attachmentsOf(images) }), ...(search && { webSearch: true }) });
      if (text !== "") chats.setFirstMessage(started.conversationId, text);
      // The conversation shows the message at once, before its transcript is read.
      if (started.admission !== "duplicate") chats.addSent(started.conversationId, { text, images: images.map(({ mimeType, data }) => ({ mimeType, data })), before: 0 });
      chats.reload();
      navigate(pagePath("/conversations", started.conversationId));
    } catch (thrown) {
      setError(thrown instanceof Error ? thrown : new Error(String(thrown)));
      throw thrown;
    }
  };

  // The last conversations, to continue: one per key (a reset's previous ones are not suggested).
  const recent = (chats.items ?? []).filter((conversation) => conversation.key !== undefined && conversation.current !== false).slice(0, SUGGESTED);

  return (
    <div className="min-h-0 flex-1 overflow-y-auto">
      <div className="mx-auto flex min-h-full max-w-[720px] flex-col justify-center px-4 py-10 sm:px-8">
        <h1 className="text-[26px] font-normal tracking-[-0.02em] text-ink">
          <span className="new-chat-reveal block text-ink-3" style={revealStyle(stage >= 1)}>
            Hello{operator === undefined || operator === "operator" ? "" : ` ${operator}`}
          </span>
          <span className="new-chat-reveal block" style={revealStyle(stage >= 2)}>
            What can I help you with?
          </span>
        </h1>

        <div className="chat new-chat-reveal relative mt-7" style={revealStyle(stage >= 3)}>
          <PromptBar
            autoFocus
            placeholder={chosen === undefined ? "The App has no agent to talk to" : `Ask ${assistantName(chosen)} anything…`}
            disabled={chosen === undefined}
            picker={{
              label: "assistant",
              options: assistantOptions(agents, (name) => (name === fallback && agents.length > 1 ? "default" : undefined)),
              value: chosen,
              onChange: setAgent,
            }}
            images={imageLimits(app)}
            webSearch={webSearch}
            commands={commands ?? []}
            commandsNote="Commands run in a conversation: start one, then run them there"
            onCommand={(name) => {
              setError(new Error(`/${name} runs in a conversation: start one with a first message, then run it there.`));
              throw new Error("no conversation");
            }}
            onSend={start}
          />
          {error !== undefined && (
            <div className="mt-3">
              <ErrorNote error={error} title="Not started" />
            </div>
          )}
        </div>

        <div className="new-chat-reveal mt-6 flex flex-col" style={revealStyle(stage >= 4)}>
          {recent.map((conversation) => {
            const title = chats.titleOf(conversation);
            return (
              <Link
                key={conversation.conversationId}
                to={pagePath("/conversations", conversation.conversationId)}
                className="-mx-2 flex items-center gap-3 rounded-control px-2 py-2.5 text-left text-[14px] text-ink transition-colors duration-150 hover:bg-hover"
              >
                <span className="flex w-[15px] shrink-0 justify-center text-ink-3">
                  <ChatBubble width={15} height={15} strokeWidth={1.9} />
                </span>
                <span className="min-w-0 truncate">Continue {title === NEW_CHAT ? `the chat with ${conversation.agent === undefined ? "the assistant" : assistantName(conversation.agent)}` : title}</span>
              </Link>
            );
          })}
          <div className="mt-1 flex flex-wrap items-center gap-x-5 gap-y-1 pl-0.5 text-[13px] text-ink-3">
            <span className="flex items-center gap-2 py-1">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor" aria-hidden>
                <circle cx="5" cy="12" r="1.7" />
                <circle cx="12" cy="12" r="1.7" />
                <circle cx="19" cy="12" r="1.7" />
              </svg>
              Only you see this conversation and its answers
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * A conversation as the admin API serves it (`/admin/api/conversations/:id/…`), for the shared view
 * (`components/pikit/conversation.tsx`): its transcript, its live events, a message (with images, a web
 * search) and a stop. A view that only follows one live passes it to `useLive`.
 */

import type { ConversationSource } from "@/components/pikit/conversation";
import { api, type ApiPage, type ApiSendResponse, type ApiTranscriptEntry, follow, post } from "@/lib/api";
import { attachmentsOf } from "./composer";

export function adminSource(id: string): ConversationSource {
  const path = `/conversations/${encodeURIComponent(id)}`;
  return {
    id,
    transcript: ({ limit, cursor }) => api<ApiPage<ApiTranscriptEntry>>(`${path}/transcript?limit=${limit}${cursor === undefined ? "" : `&cursor=${encodeURIComponent(cursor)}`}`),
    follow: (onEvent, signal) => follow(`${path}/events`, onEvent, signal),
    send: ({ text, images, webSearch }) =>
      post<ApiSendResponse>(`${path}/messages`, {
        text,
        ...(images.length > 0 && { attachments: attachmentsOf(images) }),
        ...(webSearch && { webSearch: true }),
      }),
    abort: async () => {
      await post(`${path}/abort`);
    },
  };
}
